public class DefaultClientAuthenticator : PopupKeyStorePasswordProvider, ClientAuthenticator {

	private Authenticator authenticator = new _Anon_Authenticator_1();

	/**
	 * Produce minimal URL (i.e., protocol, host and port)
	 * @param url request URL
	 * @return minimal URL
	 */
	public static URL getMinimalURL(URL url) {
		try {
			URI uri = url.toURI();
			if (uri.isOpaque()) {
				// Can't easily simplify - GhidraURL could help but is not visible 
				return url;
			}
			return uri.resolve("/").toURL();
		}
		catch (Exception e) when (e is MalformedURLException or URISyntaxException) {
			// ignore
		}
		return null;
	}

